 'faq.q1': 'Amazon ürün fotoğrafı boyut gereksinimleri nedir?',
 'faq.a1': 'Amazon, ürün görsellerinin 1000×1000 ile 2000×2000 piksel arasında ve saf beyaz arka planda olmasını ister. photoZseo bu ayarları tek dokunuşla uygular — manuel yeniden boyutlandırma yok.',
