 'privacy.collection.desc': 'photoZseo tüm görselleri tamamen cihazınızda işler. Fotoğraflarınızı herhangi bir sunucuya yüklemez, saklamaz veya iletmeyiz.',
 'privacy.collection.photos': 'Fotoğraflar ve Görseller: Cihazınızda yerel olarak işlenir. Asla sunucularımıza gönderilmez.',
 'privacy.collection.account': 'Hesap Bilgileri: photoZseo hesap gerektirmez. E-posta, kullanıcı adı veya kişisel bilgi toplanmaz.',
 'privacy.collection.purchase': 'Satın Alma Verileri: Abonelik ve satın alma bilgileri Apple (App Store) tarafından yönetilir. Ödeme bilgilerinize erişimimiz yoktur.',
 'privacy.collection.diagnostic': 'Tanılama Verileri: Hataları düzeltmemize ve kararlılığı artırmamıza yardımcı olmak için anonim çökme günlükleri ve performans metrikleri toplanabilir. Kişisel tanımlayıcı yok, reklam kimliği yok, izleme yok.',
 'privacy.thirdparty.title': 'Üçüncü Taraf Hizmetler',
 'privacy.thirdparty.apple': 'Apple App Store: Satın alma ve abonelikleri yönetir.',
 'privacy.thirdparty.revenuecat': 'RevenueCat: Abonelik durumunu yönetir. Gizlilik politikalarını revenuecat.com/privacy adresinde inceleyin.',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics (Google): Anonim çökme raporları ve performans tanılama verileri toplar. IDFA yok, reklam izleme yok. Bkz: firebase.google.com/support/privacy.',
 'privacy.thirdparty.shopify': 'Shopify (yalnızca dışa aktarım): photoZseo Shopify\'ın sunucularına bağlanmaz. Uygulama ürün listenizi CSV, XLSX veya DOCX dosyaları olarak dışa aktarır; bu dosyayı Shopify Admin\'e siz yüklersiniz. Verileriniz cihazınızdan ancak siz aktif olarak dışa aktarım dosyasını paylaştığınızda veya yüklediğinizde çıkar.',
 'privacy.storage.title': 'Veri Depolama',
 'privacy.storage.desc': 'Tüm proje verileri, görseller ve ayarlar cihazınızda şifrelenmiş sandbox depolamada yerel olarak saklanır. İstediğiniz zaman uygulamanın Ayarlar bölümünden tüm verileri silebilirsiniz.',
 'privacy.camera.title': 'Kamera ve Fotoğraf Kitaplığı Erişimi',
 'privacy.camera.desc': 'Uygulama, ürün fotoğraflarını çekmek ve içe aktarmak için kameranıza ve fotoğraf kitaplığınıza erişim ister. Bu izinler isteğe bağlıdır ve cihaz ayarlarınızdan istediğiniz zaman iptal edilebilir.',
 'privacy.biometric.title': 'Biyometrik Kimlik Doğrulama',
 'privacy.biometric.desc': 'photoZseo, Face ID, Touch ID veya cihaz parolası kullanarak isteğe bağlı bir Uygulama Kilidi özelliği sunar. Biyometrik veriler tamamen cihazınızın işletim sistemi tarafından işlenir — photoZseo biyometrik verilerinize asla erişmez, saklamaz veya iletmez.',
 'privacy.children.title': 'Çocukların Gizliliği',
 'privacy.children.desc': 'photoZseo 13 yaşın altındaki çocuklara yönelik değildir. Çocuklardan bilerek kişisel bilgi toplamayız.',
 'privacy.changes.title': 'Politika Değişiklikleri',
 'privacy.changes.desc': 'Bu politikayı zaman zaman güncelleyebiliriz. Önemli değişiklikleri uygulama veya bu sayfa aracılığıyla bildiririz.',
 'privacy.contact.title': 'İletişim',
 'privacy.contact.desc': 'Bu gizlilik politikası hakkında sorularınız varsa bize ulaşın:',
 'terms.title': 'Kullanım Koşulları',
 'terms.updated': 'Son güncelleme:',
 'terms.date': '21 Nisan 2026',
 'terms.acceptance.title': 'Koşulların Kabulü',
 'terms.acceptance.desc': 'photoZseo\'yu indirerek veya kullanarak bu Kullanım Koşullarını kabul etmiş olursunuz. Kabul etmiyorsanız uygulamayı kullanmayın.',
 'terms.description.title': 'Hizmet Açıklaması',
 'terms.description.desc': 'photoZseo, e-ticaret satıcılarının ürün fotoğraflarını boyutlandırma, sıkıştırma ve SEO uyumlu dosya adları oluşturarak optimize etmelerine yardımcı olan bir mobil uygulamadır. Tüm görsel işleme cihazınızda yerel olarak gerçekleştirilir.',
 'terms.subscriptions.title': 'Abonelikler ve Ödemeler',
 'terms.subscriptions.f1': 'photoZseo, filigranlı dışa aktarma ile ücretsiz katman ve tam özellikler için Pro abonelik sunar.',
 'terms.subscriptions.f2': 'Abonelikler Apple ID (App Store) üzerinden faturalandırılır.',
 'terms.subscriptions.f3': 'Abonelikler, mevcut dönemin bitiminden en az 24 saat önce iptal edilmediği sürece otomatik olarak yenilenir.',
 'terms.subscriptions.f4': 'Abonelikleri cihazınızın Ayarlarından yönetebilir veya iptal edebilirsiniz (Apple ID > Abonelikler).',
 'terms.subscriptions.f5': 'İadeler Apple tarafından ilgili iade politikalarına uygun olarak işlenir.',
 'terms.plans.title': 'Abonelik Planları',
 'terms.plans.note': 'Tüm fiyatlar USD cinsindendir. Yerel para birimi karşılıkları App Store tarafından bölgenize göre belirlenir.',
 'terms.plans.weekly': 'Haftalık — $2.99 / hafta',
 'terms.plans.monthly': 'Aylık — 3 gün ücretsiz deneme, ardından $6.99 / ay',
 'terms.plans.quarterly': '3 Aylık — $12.99 / 3 ay (%38 tasarruf, ~$4.33/ay)',
 'terms.plans.annual': 'Yıllık — $39.99 / yıl (%52 tasarruf, ~$3.33/ay)',
 'terms.trial.title': 'Ücretsiz Deneme',
 'terms.trial.desc': 'Ücretsiz deneme sunuluyorsa, önceden iptal edilmediği sürece deneme süresinin sonunda otomatik olarak ücretli aboneliğe dönüşür.',
 'terms.ip.title': 'Fikri Mülkiyet',
 'terms.ip.desc': 'Uygulama, tasarımı, kodu ve markası photoZseo\'nun mülkiyetindedir. Uygulama kullanılarak işlediğiniz fotoğrafların tam mülkiyeti size aittir.',
 'terms.use.title': 'Kabul Edilebilir Kullanım',
 'terms.use.desc': 'Aşağıdakileri yapmamayı kabul edersiniz:',
 'terms.use.f1': 'Uygulamayı tersine mühendislik, derlemeyi çözme veya parçalarına ayırma.',
 'terms.use.f2': 'Uygulamayı herhangi bir yasa dışı amaçla kullanma.',
 'terms.use.f3': 'Uygulamayı veya özelliklerini yeniden dağıtma veya yeniden satma.',
 'terms.disclaimer.title': 'Sorumluluk Reddi',
 'terms.disclaimer.desc': 'photoZseo herhangi bir garanti olmaksızın "olduğu gibi" sunulur. Uygulamanın kullanımından kaynaklanan herhangi bir veri kaybı veya hasardan sorumlu değiliz.',
 'terms.liability.title': 'Sorumluluk Sınırlaması',
 'terms.liability.desc': 'Yasaların izin verdiği azami ölçüde, photoZseo uygulamanın kullanımından kaynaklanan herhangi bir dolaylı, arızi veya sonuç olarak ortaya çıkan zararlardan sorumlu olmayacaktır.',
 'terms.changes.title': 'Koşul Değişiklikleri',
 'terms.changes.desc': 'Bu koşulları istediğimiz zaman güncelleme hakkını saklı tutarız. Değişikliklerden sonra uygulamayı kullanmaya devam etmeniz güncellenmiş koşulların kabulü anlamına gelir.',
