 'support.faq.upgrade.q': 'Pro\'ya nasıl yükseltirim?',
 'support.faq.upgrade.a': 'Uygulamayı açın, Ayarlar\'a gidin ve "Pro\'ya Yükselt"e dokunun. Haftalık, aylık, 3 aylık veya yıllık planlar arasından seçim yapabilirsiniz.',
