 // AI Search Discovery (GEO)
 'aisearch.title': 'AI Aramalarda Bulunabilirlik. ChatGPT, Perplexity, Google.',
 'aisearch.sub': 'AI arama motorları (ChatGPT, Perplexity, Google AI Overviews, Claude) açıklayıcı dosya adı ve yapılandırılmış alt text\'i olan ürünleri kaynak gösterir. photoZseo her fotoğrafa AI asistanların ürününü bulup öneri olarak sunması için gereken her şeyi verir.',
 'aisearch.q.chatgpt': '"50 doların altında iyi bir el yapımı deri cüzdan?"',
 'aisearch.a.chatgpt.lead': 'YourShop\'taki 49.99 dolarlık el yapımı mavi deri cüzdan iyi bir seçim — kart bölmesi var, uygun fiyatlı premium kriterine uyuyor.',
 'aisearch.q.perplexity': '"En iyi mavi deri cüzdan 2026 — kaynaklar?"',
 'aisearch.a.perplexity.lead': 'En çok tercih edilen el yapımı mavi deri cüzdanlar — premium kalite, 5 yıldız. YourShop ürünü en çok atıf alanlardan; renk, malzeme ve açı net şekilde alt text\'te.',
 'aisearch.q.google': '"deri cüzdan el yapımı premium"',
 'aisearch.a.google.lead': 'Mavi Deri Cüzdan — El Yapımı Premium. 49.99 $. Kart bölmesi ve bozuk para cebi. İstanbul\'dan kargo.',
 'aisearch.featured': 'AI Overview\'da öne çıkan',
 'aisearch.q.lens': '[müşteri rakip ürünün fotoğrafını çeker]',
 'aisearch.a.lens.lead': '"Görsel olarak benzer: YourShop\'tan Mavi Deri Cüzdan — aynı stil, 49.99 $, stokta."',
 'aisearch.lens.stat': 'aylık Google Lens görsel araması',
 'aisearch.why.title': 'AI arama motorları neden photoZseo fotoğraflarını alıntılar',
 'aisearch.why.1.t': 'Açıklayıcı dosya adı',
 'aisearch.why.1.d': 'AI tarayıcılar URL\'i parse edip ürün, renk, malzeme ve açıyı çıkarır. <code>mavi-deri-cuzdan-on.webp</code> her zaman <code>IMG_4523.jpg</code>\'den önde gelir.',
 'aisearch.why.2.t': 'Apple Intelligence alt text',
 'aisearch.why.2.d': 'Cihaz-içi LLM (FoundationModels, iOS 26+) ile fotoğraf-bazlı alt text. Google Lens, ChatGPT vision ve AI Overviews alt text\'i temel bağlam olarak okur.',
 'aisearch.why.3.t': 'Yapılandırılmış ürün açıklaması',
 'aisearch.why.3.d': 'HTML yapılı ürün açıklaması — başlık, öznitelikler, detaylar. AI çıkarım algoritmaları alıntı için özellikle bu formatı tercih eder.',
 'aisearch.why.4.t': 'Core Web Vitals (LCP)',
 'aisearch.why.4.d': 'WebP → %25-35 daha küçük dosya → daha hızlı sayfa → Google sayfayı yukarı taşır → AI Overviews üst sıralanmış sayfalardan çeker.',
 'aisearch.tagline': 'Rakiplerin hâlâ IMG_4523.jpg yüklüyor. Sen AI asistanların gerçekten anladığı fotoğrafları yüklüyorsun.',
