 'features.camera.title': 'Estudio de Cámara Pro',
 'features.camera.desc': 'Cámara integrada con enfoque táctil, cuadrícula, indicador de nivel, modo de disparo direccional, ráfaga y obturador por volumen.',
 'features.archive.title': 'Archivo de Proyectos',
 'features.archive.desc': 'Organiza todas tus fotos de producto en carpetas estilo Apple Files. Un proyecto por producto — carpetas con colores, arrastrar y soltar, renombrar, duplicar.',
 'features.resize.title': 'Recorte y Compresión Automáticos',
 'features.resize.desc': 'Recorte, redimensión y compresión automáticos según las especificaciones de cada plataforma. Modo calidad o modo tamaño de archivo objetivo. Salida JPEG, PNG, WebP.',
 'features.seo.title': 'Nombres SEO y Texto Alt',
 'features.seo.desc': 'Genera automáticamente nombres de archivo y texto alternativo optimizados para búsqueda a partir del nombre del producto y etiquetas de dirección. Soporte Unicode para cualquier idioma.',
 'features.presets.title': 'Presets de Plataforma',
 'features.presets.desc': 'Presets de un toque para Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok. Tamaño, formato y calidad — todo preconfigurado.',
 'features.video.title': 'Video de Producto',
 'features.video.desc': 'Graba videos de producto directamente en la app. Recorte y redimensión automáticos a las dimensiones de tu proyecto. Perfecto para Reels, TikTok y listados.',
 'features.bgremoval.title': 'Eliminación de Fondo',
 'features.bgremoval.desc': 'Eliminación de fondo con IA en un toque. Reemplaza con blanco, negro, color personalizado o PNG transparente para listados profesionales.',
 'features.logo.title': 'Logo y Marca de Agua',
 'features.logo.desc': 'Añade tu logo de marca a cada exportación. Elige entre 9 posiciones, ajusta tamaño y opacidad. Tu marca, automatizada.',
