 'delete.notaffected.title': 'Qué No se Afecta',
 'delete.notaffected.f1': 'Fotos previamente guardadas en la Biblioteca de Fotos de su dispositivo',
 'delete.notaffected.f2': 'Su suscripción (gestione por separado en Configuración > Apple ID > Suscripciones)',
 'delete.warning': 'La eliminación de datos es permanente y no se puede deshacer.',
