 'rename.sub': 'Cambie el nombre del producto una vez. La aplicación se conecta en cascada y cambia a través de slug, texto alternativo, título SEO, meta descripción, descripción del producto, todos los nombres de archivos en el disco y la carpeta del proyecto, de forma atómica.',
