 'archive.f.contact.d': 'Agrupar productos por nombre de cliente o empresa. Teléfono, correo electrónico, dirección, foto, etiqueta de color, todo en un solo lugar.',
 'archive.f.folder.t': 'Carpetas inteligentes',
