 'feature.seo-filenames.title': 'SEO-Dateinamen & Alt-Text',
 'feature.seo-filenames.lead': 'Automatisch generierte suchmaschinenoptimierte Dateinamen wie blue-leather-bag-front.webp — bereit für Google Bilder, Shopify, Amazon und jeden E-Commerce-Crawler.',
 'feature.seo-filenames.b1.title': 'Rankt bei Google Bilder',
 'feature.seo-filenames.b1.desc': 'Bindestrich-getrennt, Kleinbuchstaben, plattformsicher. Das exakte Format, das Suchmaschinen für Produkt-Crawling bevorzugen.',
 'feature.seo-filenames.b2.title': 'Unicode für jede Sprache',
 'feature.seo-filenames.b2.desc': 'Türkisch, Arabisch, Japanisch, Hindi — jedes Zeichen wird bei Bedarf normalisiert und romanisiert.',
 'feature.seo-filenames.b3.title': 'Alt-Text in einem Tipp',
 'feature.seo-filenames.b3.desc': 'Beschreibender Alt-Text aus Produktname, Richtungs-Tag und Szene. Barrierefreiheit + SEO in einem Zug.',
 'feature.seo-filenames.s1.title': 'Produktnamen eingeben',
 'feature.seo-filenames.s1.desc': 'Blaue Ledertasche. Das war\'s.',
 'feature.seo-filenames.s2.title': 'Richtungs-Tag wählen',
 'feature.seo-filenames.s2.desc': 'Vorne, hinten, seitlich, Detail, oben — Dateinamen bleiben über alle Fotos organisiert.',
 'feature.seo-filenames.s3.title': 'Überall exportieren',
 'feature.seo-filenames.s3.desc': 'Der SEO-Dateiname wandert mit Ihrer Datei zu AirDrop, Shopify, E-Mail, Dateien — wohin Sie sie auch senden.',
 'feature.platform-presets.title': '46 Plattform-Presets',
 'feature.platform-presets.lead': 'Amazon verlangt 2000×2000. Etsy will 3:4. TikTok Shop bevorzugt 1:1. photoZseo weiß es bereits — Plattform wählen, wir wenden die Spezifikation an.',
 'feature.platform-presets.b1.title': 'Immer aktuell',
 'feature.platform-presets.b1.desc': 'Jede Version aktualisiert Größen-, Format- und Dateigewicht-Regeln für jeden Marktplatz. Keine veralteten Anleitungen mehr.',
 'feature.platform-presets.b2.title': 'Ein Tipp, jede Plattform',
 'feature.platform-presets.b2.desc': 'Größe ändern, komprimieren und formatieren in den exakten Specs, die Amazon, Etsy, Shopify, eBay und Walmart veröffentlichen.',
 'feature.platform-presets.b3.title': 'Batch über Plattformen',
 'feature.platform-presets.b3.desc': 'Dasselbe Foto, mehrere Plattform-Exporte in einem Durchgang — gezippt und bereit zum Upload.',
 'feature.platform-presets.s1.title': 'Plattform auswählen',
 'feature.platform-presets.s1.desc': 'Amazon, Etsy, Shopify, TikTok Shop, Instagram — 46 zur Auswahl.',
 'feature.platform-presets.s2.title': 'photoZseo wendet die Spezifikation an',
 'feature.platform-presets.s2.desc': 'Größe, Seitenverhältnis, Format, Kompression und Dateiname alles korrekt eingestellt.',
 'feature.platform-presets.s3.title': 'Exportieren & hochladen',
 'feature.platform-presets.s3.desc': 'Export zu Shopify (CSV/XLSX/DOCX), AirDrop, Dateien, Mail oder ein ZIP — bereit für Bulk-Upload.',
 'home.bandlabel': 'Optimiert für 46 Plattformen',
 'home.howitworks': 'So funktioniert es',
 'home.howitworks.sub': 'Drei Schritte. Eine App. Jede Plattform.',
 'home.step.shoot': 'Fotografieren',
 'home.step.shoot.desc': 'Kamera öffnen. Zuschneidelinien, Raster, Wasserwaage und Richtungs-Tags sind bereit. Einfach den Auslöser drücken.',
 'home.step.optimize': 'Optimieren',
 'home.step.optimize.desc': 'photoZseo schneidet zu, skaliert, komprimiert, benennt mit SEO-Keywords um und erstellt Alt-Texte. Alles im Hintergrund.',
 'home.step.sell': 'Verkaufen',
 'home.step.sell.desc': 'Als CSV/XLSX/DOCX exportieren, per AirDrop teilen oder an Shopify übergeben. Ihre Fotos sind plattformfertig — hochladen und verkaufen.',
