 'archive.f.contact.d': 'Gruppieren Sie Produkte nach Kunden- oder Firmennamen. Telefon, E-Mail, Adresse, Foto, Farbmarkierung – alles an einem Ort.',
 'archive.f.folder.t': 'Intelligente Ordner',
