 // FAQ
 'faq.title': 'よくある質問',
 'faq.sub': '販売者がダウンロード前に尋ねるすべて。',
 'faq.q1': 'Amazonの商品写真のサイズ要件は何ですか？',
 'faq.a1': 'Amazonは純白背景で1000×1000〜2000×2000ピクセルの商品画像を要求します。photoZseoはこれらの仕様をワンタップで適用します — 手動リサイズ不要。',
 'faq.q2': '最適なユニバーサル商品写真サイズは？',
 'faq.a2': '2000×2000ピクセル、正方形（1:1）、白背景 — Amazon、Etsy、Shopify、eBay、Walmartなど、ほぼすべてのマーケットプレイスの要件を満たします。',
 'faq.q3': 'photoZseoは何のプラットフォームに対応していますか？',
 'faq.a3': 'Amazon、Walmart、Etsy、Shopify、eBay、TikTok Shop、Instagram Shopping、Trendyol、Hepsiburada、Poshmark、Pinterest、Mercado Libre、AliExpressを含む60以上のプラットフォーム。',
 'faq.q4': 'インターネットなしで動作しますか？',
 'faq.a4': 'はい。リサイズ、圧縮、SEO名前付け、背景除去はすべて100%デバイス上で実行されます。アップロードなし、クラウドなし、アカウント不要。',
 'faq.q5': '無料プランはありますか？',
 'faq.a5': 'はい。無料プランには無制限のプロジェクトとすべての主要機能が含まれます。エクスポートには小さなphotoZseoウォーターマークとファイル名タグが付きます；Proは両方を削除します。',
 'faq.q6': 'サブスクリプションはいつでもキャンセルできますか？',
 'faq.a6': 'はい。サブスクリプションはApp Storeを通じて請求され、設定 → Apple ID → サブスクリプションからいつでもキャンセルできます。現在の期間終了までProは利用可能です。',
 'faq.q7': '写真はどこに行きますか？どこかにアップロードされますか？',
 'faq.a7': 'どこにも行きません。photoZseoはすべての写真をデバイス上で処理します。あなた自身が共有、エクスポート、プッシュしない限り、画像もメタデータもスマートフォンから出ません。',

