 'privacy.thirdparty.revenuecat': 'RevenueCat：サブスクリプション状態を管理。プライバシーポリシーの詳細はrevenuecat.com/privacyをご覧ください。',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics（Google）：匿名のクラッシュレポートとパフォーマンス診断を収集します。IDFA なし、広告トラッキングなし。詳細は firebase.google.com/support/privacy をご覧ください。',
 'privacy.thirdparty.shopify': 'Shopify（エクスポートのみ）：photoZseo は Shopify のサーバーには接続しません。アプリは商品リストを CSV、XLSX または DOCX ファイルとしてエクスポートします。そのファイルはユーザー自身が Shopify Admin にアップロードします。データは、ユーザーがエクスポートファイルを共有またはアップロードしたときにのみ端末から離れます。',
 'privacy.storage.title': 'データ保存',
 'privacy.storage.desc': 'すべてのプロジェクトデータ、画像、設定は暗号化されたサンドボックスストレージを使用してデバイス上にローカルに保存されます。アプリの設定からいつでもすべてのデータを削除できます。',
 'privacy.camera.title': 'カメラとフォトライブラリへのアクセス',
 'privacy.camera.desc': 'アプリは商品写真の撮影とインポートのためにカメラとフォトライブラリへのアクセスを要求します。これらの権限はオプションであり、デバイスの設定からいつでも取り消すことができます。',
 'privacy.biometric.title': '生体認証',
 'privacy.biometric.desc': 'photoZseoはFace ID、Touch ID、またはデバイスのパスコードを使用したオプションのアプリロック機能を提供します。生体認証データはデバイスのオペレーティングシステムによって完全に処理されます — photoZseoは生体認証データにアクセス、保存、送信することはありません。',
