 'faq.q1': 'Quais são os requisitos de tamanho de foto de produto da Amazon?',
 'faq.a1': 'A Amazon exige imagens de produto entre 1000×1000 e 2000×2000 pixels em fundo branco puro. photoZseo aplica essas especificações com um único toque — sem redimensionamento manual.',
