 'privacy.title': 'Política de Privacidade',
 'privacy.updated': 'Última atualização:',
 'privacy.date': '21 de abril de 2026',
 'privacy.overview.title': 'Visão Geral',
 'privacy.overview.desc': 'photoZseo ("nós", "nosso", "o aplicativo") está comprometido em proteger sua privacidade. Esta política explica como tratamos seus dados.',
 'privacy.collection.title': 'Coleta de Dados',
 'privacy.collection.desc': 'photoZseo processa todas as imagens inteiramente no seu dispositivo. Não fazemos upload, armazenamos ou transmitimos suas fotos para nenhum servidor.',
 'privacy.collection.photos': 'Fotos e Imagens: Processadas localmente no seu dispositivo. Nunca enviadas aos nossos servidores.',
 'privacy.collection.account': 'Informações da Conta: photoZseo não requer uma conta. Nenhum e-mail, nome de usuário ou informação pessoal é coletado.',
 'privacy.collection.purchase': 'Dados de Compra: Informações de assinatura e compra são gerenciadas pela Apple (App Store). Não temos acesso aos seus dados de pagamento.',
 'privacy.collection.diagnostic': 'Dados de Diagnóstico: Relatórios anônimos de falhas e métricas de desempenho podem ser coletados para nos ajudar a corrigir bugs e melhorar a estabilidade. Sem identificadores pessoais, sem ID de publicidade, sem rastreamento.',
 'privacy.thirdparty.title': 'Serviços de Terceiros',
 'privacy.thirdparty.apple': 'Apple App Store: Gerencia compras e assinaturas.',
 'privacy.thirdparty.revenuecat': 'RevenueCat: Gerencia o status da assinatura. Consulte a política de privacidade em revenuecat.com/privacy.',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics (Google): Coleta relatórios anônimos de falhas e diagnósticos de desempenho. Sem IDFA, sem rastreamento publicitário. Consulte firebase.google.com/support/privacy.',
 'privacy.thirdparty.shopify': 'Shopify (apenas exportação): o photoZseo não se conecta aos servidores do Shopify. O app exporta sua lista de produtos como arquivos CSV, XLSX ou DOCX; você faz o upload desse arquivo manualmente no seu Shopify Admin. Seus dados só saem do dispositivo quando você compartilha ou envia ativamente o arquivo de exportação.',
 'privacy.storage.title': 'Armazenamento de Dados',
 'privacy.storage.desc': 'Todos os dados do projeto, imagens e configurações são armazenados localmente no seu dispositivo em armazenamento sandbox criptografado. Você pode excluir todos os dados a qualquer momento nas Configurações do aplicativo.',
 'privacy.camera.title': 'Acesso à Câmera e Biblioteca de Fotos',
 'privacy.camera.desc': 'O aplicativo solicita acesso à sua câmera e biblioteca de fotos para capturar e importar fotos de produtos. Essas permissões são opcionais e podem ser revogadas a qualquer momento nas configurações do dispositivo.',
 'privacy.biometric.title': 'Autenticação Biométrica',
 'privacy.biometric.desc': 'photoZseo oferece um recurso opcional de Bloqueio do App usando Face ID, Touch ID ou código do dispositivo. Os dados biométricos são processados inteiramente pelo sistema operacional do seu dispositivo — photoZseo nunca acessa, armazena ou transmite seus dados biométricos.',
 'privacy.children.title': 'Privacidade de Crianças',
 'privacy.children.desc': 'photoZseo não é direcionado a crianças menores de 13 anos. Não coletamos conscientemente informações pessoais de crianças.',
 'privacy.changes.title': 'Alterações nesta Política',
 'privacy.changes.desc': 'Podemos atualizar esta política periodicamente. Notificaremos sobre mudanças significativas através do aplicativo ou nesta página.',
 'privacy.contact.title': 'Contato',
 'privacy.contact.desc': 'Se você tiver dúvidas sobre esta política de privacidade, entre em contato conosco em',
 'terms.title': 'Termos de Uso',
 'terms.updated': 'Última atualização:',
 'terms.date': '21 de abril de 2026',
 'terms.acceptance.title': 'Aceitação dos Termos',
 'terms.acceptance.desc': 'Ao baixar ou usar o photoZseo, você concorda com estes Termos de Uso. Se não concordar, não use o aplicativo.',
 'terms.description.title': 'Descrição do Serviço',
 'terms.description.desc': 'photoZseo é um aplicativo móvel que ajuda vendedores de e-commerce a otimizar fotos de produtos através de redimensionamento, compressão e geração de nomes de arquivo SEO. Todo o processamento de imagens é realizado localmente no seu dispositivo.',
 'terms.subscriptions.title': 'Assinaturas e Pagamentos',
 'terms.subscriptions.f1': 'photoZseo oferece um nível gratuito com exportações com marca d\'água e uma assinatura Pro para recursos completos.',
 'terms.subscriptions.f2': 'As assinaturas são cobradas através da sua conta Apple ID (App Store) ou conta Google.',
 'terms.subscriptions.f3': 'As assinaturas são renovadas automaticamente, a menos que sejam canceladas pelo menos 24 horas antes do final do período atual.',
 'terms.subscriptions.f4': 'Você pode gerenciar ou cancelar assinaturas nas Configurações do seu dispositivo (Apple ID > Assinaturas).',
 'terms.subscriptions.f5': 'Reembolsos são processados pela Apple de acordo com suas respectivas políticas de reembolso.',
 'terms.plans.title': 'Planos de Assinatura',
 'terms.plans.note': 'Todos os preços em USD. Os equivalentes em moeda local são definidos pela App Store com base na sua região.',
 'terms.plans.weekly': 'Semanal — $2.99 / semana',
 'terms.plans.monthly': 'Mensal — Teste gratuito de 3 dias, depois $6.99 / mês',
 'terms.plans.quarterly': 'Trimestral — $12.99 a cada 3 meses (economize 38%, ~$4.33/mês)',
