 'terms.trial.title': 'Teste Gratuito',
 'terms.trial.desc': 'Se um teste gratuito for oferecido, ele será automaticamente convertido em uma assinatura paga ao final do período de teste, a menos que seja cancelado antes.',
 'terms.ip.title': 'Propriedade Intelectual',
 'terms.ip.desc': 'O aplicativo, seu design, código e marca são propriedade do photoZseo. Você mantém a propriedade total de quaisquer fotos que processar usando o aplicativo.',
 'terms.use.title': 'Uso Aceitável',
 'terms.use.desc': 'Você concorda em não:',
