 'terms.use.f3': 'Redistribuir ou revender o aplicativo ou seus recursos.',
 'terms.disclaimer.title': 'Isenção de Responsabilidade',
 'terms.disclaimer.desc': 'photoZseo é fornecido "como está" sem garantias de qualquer tipo. Não somos responsáveis por qualquer perda de dados ou danos resultantes do uso do aplicativo.',
 'terms.liability.title': 'Limitação de Responsabilidade',
 'terms.liability.desc': 'Na máxima extensão permitida por lei, photoZseo não será responsável por quaisquer danos indiretos, incidentais ou consequentes decorrentes do uso do aplicativo.',
 'terms.changes.title': 'Alterações nos Termos',
 'terms.changes.desc': 'Reservamo-nos o direito de atualizar estes termos a qualquer momento. O uso continuado do aplicativo após alterações constitui aceitação dos termos atualizados.',
