 'support.contact.email': 'Email:',
 'support.contact.response': 'Nosso objetivo é responder dentro de 48 horas.',
 'support.faq.title': 'Perguntas Frequentes',
 'support.faq.upgrade.q': 'Como faço upgrade para Pro?',
 'support.faq.upgrade.a': 'Abra o aplicativo, vá para Configurações e toque em "Upgrade para Pro". Você pode escolher entre planos semanal, mensal, trimestral ou anual.',
 'support.faq.restore.q': 'Como restauro minha compra?',
 'support.faq.restore.a': 'Vá para Configurações no aplicativo e toque em "Restaurar Compras". Certifique-se de estar conectado com o mesmo Apple ID usado na compra original.',
 'support.faq.cancel.q': 'Como cancelo minha assinatura?',
 'support.faq.cancel.a': 'Abra Configurações > Apple ID > Assinaturas > photoZseo > Cancelar Assinatura. Seus recursos Pro permanecerão ativos até o final do período de cobrança atual.',
 'support.faq.privacy.q': 'Minhas fotos são enviadas para um servidor?',
 'support.faq.privacy.a': 'Não. Todo o processamento de imagens acontece inteiramente no seu dispositivo. Suas fotos nunca são enviadas para nenhum servidor.',
 'support.faq.platforms.q': 'Quais plataformas são suportadas?',
 'support.faq.platforms.a': 'photoZseo suporta presets otimizados para Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok e formatos web personalizados.',
 'support.faq.bug.q': 'Encontrei um bug. Como reporto?',
 'support.faq.bug.a': 'Envie um e-mail para support@photozseo.com com uma descrição do problema e seu modelo de dispositivo e versão do SO.',
 'delete.title': 'Excluir seus Dados',
 'delete.intro': 'photoZseo não requer uma conta. Todos os dados são armazenados localmente no seu dispositivo. Você pode excluir todos os dados do aplicativo usando os métodos abaixo.',
