 'delete.email.title': 'Opção 2: Por Email',
 'delete.email.desc': 'Se não conseguir acessar o aplicativo, envie um e-mail para support@photozseo.com com o assunto "Excluir Meus Dados" e nós o guiaremos pelo processo.',
 'delete.email.response': 'Responderemos dentro de 48 horas.',
