 // FAQ
 'faq.title': 'सामान्य प्रश्न',
 'faq.sub': 'डाउनलोड से पहले विक्रेता जो सब पूछते हैं।',
 'faq.q1': 'Amazon उत्पाद फ़ोटो के आकार की आवश्यकताएँ क्या हैं?',
 'faq.a1': 'Amazon को शुद्ध सफ़ेद पृष्ठभूमि पर 1000×1000 से 2000×2000 पिक्सेल के उत्पाद चित्र चाहिए। photoZseo इन विनिर्देशों को एक टैप में लागू करता है — कोई मैनुअल आकार बदलाव नहीं।',
 'faq.q2': 'सर्वश्रेष्ठ सार्वभौमिक उत्पाद फ़ोटो आकार क्या है?',
 'faq.a2': '2000×2000 पिक्सेल, वर्ग (1:1), सफ़ेद पृष्ठभूमि — लगभग हर मार्केटप्लेस की आवश्यकताओं को पूरा करता है: Amazon, Etsy, Shopify, eBay, Walmart और अधिक।',
 'faq.q3': 'photoZseo कितने प्लेटफ़ॉर्म का समर्थन करता है?',
 'faq.a3': 'Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre और AliExpress सहित 46 प्लेटफ़ॉर्म।',
 'faq.q4': 'क्या यह इंटरनेट के बिना काम करता है?',
 'faq.a4': 'हाँ। आकार बदलना, कम्प्रेशन, SEO नाम बदलना और पृष्ठभूमि हटाना 100% आपके डिवाइस पर चलता है। कोई अपलोड नहीं, कोई क्लाउड नहीं, कोई खाता नहीं।',
 'faq.q5': 'क्या कोई मुफ़्त योजना है?',
 'faq.a5': 'हाँ। मुफ़्त योजना में असीमित प्रोजेक्ट और सभी मुख्य सुविधाएँ शामिल हैं। निर्यात में एक छोटा photoZseo वॉटरमार्क और फ़ाइलनाम टैग होता है; Pro दोनों हटा देता है।',
 'faq.q6': 'क्या मैं किसी भी समय सदस्यता रद्द कर सकता हूँ?',
 'faq.a6': 'हाँ। सदस्यताएँ App Store के माध्यम से बिल की जाती हैं और सेटिंग्स → Apple ID → सदस्यताएँ से कभी भी रद्द की जा सकती हैं। वर्तमान अवधि के अंत तक Pro चलता रहेगा।',
 'faq.q7': 'मेरी तस्वीरें कहाँ जाती हैं? क्या उन्हें कहीं अपलोड किया जाता है?',
 'faq.a7': 'कहीं नहीं। photoZseo हर तस्वीर को डिवाइस पर प्रोसेस करता है। जब तक आप स्वयं साझा, निर्यात या पुश नहीं करते, तब तक कोई भी छवि या मेटाडेटा आपके फ़ोन से बाहर नहीं जाता।',

