 'faq.a2': '2000×2000 بكسل، مربع (1:1)، خلفية بيضاء — يلبي متطلبات كل سوق تقريبًا: أمازون، Etsy، Shopify، eBay، Walmart والمزيد.',
 'faq.q3': 'كم عدد المنصات التي يدعمها photoZseo؟',
 'faq.a3': 'أكثر من 60 منصة بما في ذلك أمازون، Walmart، Etsy، Shopify، eBay، TikTok Shop، Instagram Shopping، Trendyol، Hepsiburada، Poshmark، Pinterest، Mercado Libre وAliExpress.',
 'faq.q4': 'هل يعمل بدون إنترنت؟',
 'faq.a4': 'نعم. جميع عمليات تغيير الحجم والضغط وإعادة التسمية SEO وإزالة الخلفية تتم 100% على جهازك. بدون تحميل، بدون سحابة، بدون حساب.',
 'faq.q5': 'هل هناك خطة مجانية؟',
 'faq.a5': 'نعم. تتضمن الخطة المجانية مشاريع غير محدودة وجميع الميزات الأساسية. تحمل عمليات التصدير علامة مائية photoZseo صغيرة وعلامة اسم الملف؛ يزيل Pro كليهما.',
 'faq.q6': 'هل يمكنني إلغاء الاشتراك في أي وقت؟',
 'faq.a6': 'نعم. تتم فوترة الاشتراكات عبر App Store ويمكن إلغاؤها في أي وقت من الإعدادات → Apple ID → الاشتراكات. يستمر Pro حتى نهاية الفترة الحالية.',
 'faq.q7': 'إلى أين تذهب صوري؟ هل يتم تحميلها في أي مكان؟',
 'faq.a7': 'إلى لا مكان. يعالج photoZseo كل صورة على الجهاز. لن تغادر أي صورة أو بيانات وصفية هاتفك ما لم تقم أنت بمشاركتها أو تصديرها أو دفعها.',

