 'features.video.desc': 'ویدیوهای محصول را مستقیماً در اپ ضبط کنید. برش و تغییر اندازه خودکار به ابعاد پروژه. عالی برای Reels، TikTok و آگهی‌ها.',
 'features.bgremoval.title': 'حذف پس‌زمینه',
 'features.bgremoval.desc': 'حذف پس‌زمینه با هوش مصنوعی با یک ضربه. جایگزینی با سفید، سیاه، رنگ سفارشی یا PNG شفاف برای آگهی‌های حرفه‌ای.',
 'features.logo.title': 'لوگو و واترمارک',
 'features.logo.desc': 'لوگوی برند خود را به هر خروجی اضافه کنید. از ۹ موقعیت انتخاب کنید، اندازه و شفافیت را تنظیم کنید. برندسازی شما، خودکار.',
 'features.batch.title': 'صدور دسته‌ای و Zip',
 'features.batch.desc': 'کل پروژه‌ها یا پوشه‌ها را به صورت فایل zip صادر کنید. از طریق AirDrop، ایمیل یا اپ Files به اشتراک بگذارید — آماده آپلود انبوه.',
 'features.ondevice.title': '۱۰۰٪ روی دستگاه و خصوصی',
 'features.ondevice.desc': 'تمام پردازش روی دستگاه شما انجام می‌شود. بدون آپلود، بدون فضای ابری، بدون نیاز به حساب. عکس‌های محصولات شما متعلق به شماست.',
