 'faq.q4': '인터넷 없이도 작동하나요?',
 'faq.a4': '네. 크기 조정, 압축, SEO 이름 변경 및 배경 제거는 모두 기기에서 100% 실행됩니다. 업로드 없음, 클라우드 없음, 계정 불필요.',
