 'faq.a5': '네. 무료 플랜에는 무제한 프로젝트와 모든 핵심 기능이 포함됩니다. 내보내기에는 작은 photoZseo 워터마크와 파일 이름 태그가 포함됩니다; Pro는 둘 다 제거합니다.',
