 'faq.sub': "Tout ce que les vendeurs demandent avant de télécharger.",
 'faq.q1': "Quelles sont les exigences en matière de taille de photo de produit Amazon ?",
 'faq.a1': "Amazon nécessite des images de produits comprises entre 1 000 × 1 000 et 2 000 × 2 000 pixels sur un fond blanc pur. photoZseo applique ces spécifications en un seul clic – pas de redimensionnement manuel.",
 'faq.q2': "Quelle est la meilleure taille universelle de photo de produit ?",
